import fse from 'fs-extra';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import { CLIENT_PATH } from '../constants.js';
export const setupVite = async () => {
    const entryPath = path.join(CLIENT_PATH, 'dist-cli', 'index.js');
    if (!(await fse.pathExists(entryPath))) {
        throw new Error(`Client not built. Run: cd <path>/apps/client-vite && pnpm build:cli`);
    }
    const entry = await import(pathToFileURL(entryPath).href);
    if (!entry.createCliHandler)
        throw new Error(`${entryPath} does not export createCliHandler`);
    return entry.createCliHandler();
};
